.hero {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-bg {
  background-image: url('hero.jpg');
  background-repeat: no-repeat;
  background-size: cover;
}

.nav-items {
  display: flex;
  flex-direction: row;
  gap: 16px;
  align-items: center;
}

button {
  background: #4f46e5;
  transition: background 0.2s ease;
}
button:hover {
  background: #4338ca;
}

table tr:nth-child(even) {
  background-color: #f3f4f6;
}
table tr:nth-child(odd) {
  background-color: #ffffff;
}

.icon-wrapper {
  position: relative;
}
.badge {
  position: absolute;
  top: -4px;
  right: -4px;
  background: red;
  border-radius: 50%;
}

.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 24px;
}

.thumbnail {
  transform: scale(1);
  transition: transform 0.3s ease;
}
.thumbnail:hover {
  transform: scale(1.05);
}

.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
}
.sidebar { grid-area: sidebar; }
.header { grid-area: header; }
.main { grid-area: main; }

button {
  outline: none;
}
button:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

.title {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.toast {
  animation: fadeIn 0.4s ease-in;
}

.card-list {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}
.card {
  flex: 1 1 200px;
}

.gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 10;
  background: white;
}

input[type="email"] {
  border: 1px solid #d1d5db;
  padding: 8px;
}
input[type="checkbox"] {
  accent-color: #4f46e5;
}

.steps {
  counter-reset: step;
}
.steps li {
  counter-increment: step;
}
.steps li::before {
  content: counter(step) ". ";
  font-weight: bold;
}

.gradient-card {
  border: 3px solid transparent;
  border-radius: 12px;
  background:
    linear-gradient(white, white) padding-box,
    linear-gradient(45deg, #6366f1, #ec4899) border-box;
}

.masonry {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: minmax(120px, auto);
  gap: 12px;
}

input[type="checkbox"] {
  appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid #999;
  border-radius: 4px;
}
input[type="checkbox"]:checked {
  background: #4f46e5;
  border-color: #4f46e5;
}

h1 {
  background: linear-gradient(90deg, #6366f1, #06b6d4);
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
}

.masonry-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-flow: dense;
  gap: 12px;
}

input {
  outline: none;
}
input:focus-visible {
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.4);
}

.parent {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}
.child {
  display: grid;
  grid-column: 1 / 5;
  grid-template-columns: subgrid;
}

.photo {
  filter: grayscale(100%) brightness(0.9);
  transition: filter 0.3s ease;
}
.photo:hover {
  filter: grayscale(0%) brightness(1);
}

.gallery {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
}
.gallery img {
  scroll-snap-align: start;
}

.icon-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
  gap: 8px;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
}
.card {
  container-type: inline-size;
  display: flex;
  flex-direction: column;
}
@container (min-width: 320px) {
  .card {
    flex-direction: row;
  }
}

@keyframes bounce {
  0% { transform: translateY(0); }
  30% { transform: translateY(-20px); }
  60% { transform: translateY(0); }
  80% { transform: translateY(-8px); }
  100% { transform: translateY(0); }
}
.icon {
  animation: bounce 1s ease-in-out infinite;
}

.page {
  display: grid;
  grid-template-columns: [side-start] 220px [side-end main-start] 1fr [main-end];
  grid-template-rows: [head-start] 60px [head-end body-start] 1fr [body-end];
}
.sidebar {
  grid-column: side-start / side-end;
  grid-row: body-start / body-end;
}
.main {
  grid-column: main-start / main-end;
  grid-row: body-start / body-end;
}

.page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.body-row {
  display: flex;
  flex: 1;
}
.sidebar { flex: 0 0 200px; }
.main { flex: 1; }
header, footer { flex: 0 0 auto; }

.spinner {
  width: 32px;
  height: 32px;
  border: 4px solid #e5e7eb;
  border-top-color: #4f46e5;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

@media print {
  nav, .no-print { display: none; }
  .report-section {
    break-before: page;
  }
  body {
    color: #000;
    background: #fff;
  }
}

.card {
  animation: fadeIn 0.6s ease;
}
@media (prefers-reduced-motion: reduce) {
  .card {
    animation: none;
  }
}

.masonry {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  grid-auto-rows: 10px;
  grid-auto-flow: dense;
}
.item {
  grid-row-end: span 24;
}

@property --angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.dial {
  background: conic-gradient(from var(--angle), red, blue);
  transition: --angle 0.3s ease;
}

.dashboard {
  display: grid;
  grid-template-columns: 220px 1fr 260px;
  grid-template-areas:
    "header header header"
    "sidebar main aside";
}
@media (max-width: 900px) {
  .dashboard {
    grid-template-columns: 1fr;
    grid-template-areas:
      "header"
      "main"
      "sidebar"
      "aside";
  }
}

:root {
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --color-bg: #ffffff;
  --color-text: #111827;
  --transition-base: 0.2s ease;
}
[data-theme="dark"] {
  --color-bg: #0f172a;
  --color-text: #f1f5f9;
}
@media (prefers-reduced-motion: reduce) {
  :root {
    --transition-base: 0s;
  }
}
body {
  background: var(--color-bg);
  color: var(--color-text);
  transition: background var(--transition-base), color var(--transition-base);
}
